def graph_for(board, width):
    graph = {}
    for y in range(len(board)):
        for x in range(width):
            if board[y][x] == "#":
                continue
            neighbors = []
            for step in [[0,-1,"up"],[1,0,"right"],[0,1,"down"],[-1,0,"left"]]:
                nx = x + step[0]
                ny = y + step[1]
                if 0 <= nx and nx < width and 0 <= ny and ny < len(board) and board[ny][nx] == ".":
                    neighbors.append([ny * width + nx, step[2]])
            graph[y * width + x] = neighbors
    return graph

def routes(graph, cache, start):
    if start in cache:
        return cache[start]
    queue = [start]
    table = {start: [0, None]}
    for cell in queue:
        previous = table[cell]
        for edge in graph[cell]:
            neighbor = edge[0]
            if neighbor in table:
                continue
            first = previous[1]
            if first is None:
                first = edge[1]
            table[neighbor] = [previous[0] + 1, first]
            queue.append(neighbor)
    cache[start] = table
    return table

def steps_to(table, cell):
    if cell in table:
        return table[cell][0]
    return 999

def nearest_rival(rivals, cell):
    nearest = 999
    for rival in rivals:
        steps = steps_to(rival, cell)
        if steps < nearest:
            nearest = steps
    return nearest

def rival_routes(graph, cache, width, opponents):
    result = []
    for opponent in opponents:
        result.append(routes(graph, cache, opponent["y"] * width + opponent["x"]))
    return result

def decide(state, width, graph, cache):
    player = state["player"]
    start = player[1] * width + player[0]
    items = state["items"]
    if len(items) == 0:
        return "wait"
    for item in items:
        if [item["x"], item["y"]] == player:
            return "pick"
    mine = routes(graph, cache, start)
    rivals = rival_routes(graph, cache, width, state["opponents"])
    chosen = None
    best_safe = False
    best_steps = 999
    best_lead = -999
    for item in items:
        cell = item["y"] * width + item["x"]
        if cell not in mine:
            continue
        steps = mine[cell][0]
        lead = nearest_rival(rivals, cell) - steps
        safe = lead > 0
        if chosen is None or (safe and not best_safe) or (safe == best_safe and (steps < best_steps or (steps == best_steps and lead > best_lead))):
            chosen = cell
            best_safe = safe
            best_steps = steps
            best_lead = lead
    if chosen is None:
        return "wait"
    return mine[chosen][1]

state = scan()
board = state["tiles"]
width = len(board[0])
graph = graph_for(board, width)
cache = {}
while True:
    action = decide(state, width, graph, cache)
    if action == "pick":
        pick()
    elif action == "wait":
        wait()
    else:
        move(action)
    state = scan()
